mapper.select:
SELECT EXISTS (
    SELECT 参加者番号 FROM 出欠._出欠
    WHERE
    ミーティング番号 = #{meetingNumber.value}

        AND 出欠番号 != #{attendanceNumber.value}

    AND 参加者番号 = #{participantNumber.value}
)

SELECT EXISTS (
    SELECT 参加者名 FROM 出欠._出欠
    WHERE
        ミーティング番号 = #{meetingNumber.value}

        AND 出欠番号 != #{attendanceNumber.value}

    AND 参加者名 = #{participantName.value}
)
